"#!/usr/bin/env python3\nimport sys\nimport re\n\nfilepath = sys.argv[1]\narchive_path = 'docs/archive/CHANGELOG-2026-08-17.md'\n\nwith open(filepath, 'r', encoding='utf-8') as f:\n    content = f.read()\n\n# Find all entries from 2026-08-17\npattern = r'(## 2026-08-17 — .*?)(?=## 2026-|$)'\nmatches = list(re.finditer(pattern, content, re.DOTALL))\n\nif not matches:\n    print('No 2026-08-17 entries found')\n    sys.exit(1)\n\n# Extract the entries\narchived_entries = []\nfor match in matches:\n    archived_entries.append(match.group(0))\n\n# Remove entries from main CHANGELOG\nfor match in reversed(matches):\n    content = content[:match.start()] + content[match.end():]\n\n# Create archive file with the entries\narchive_content = f'# Changelog archive — 2026-08-17\\n\\n{"".join(archived_entries)}\\n'\n\nwith open(archive_path, 'w', encoding='utf-8') as f:\n    f.write(archive_content)\n\n# Update main CHANGELOG to reference the archive\narchive_link = f'> Entries from 2026-08-17 are archived in [docs/archive/CHANGELOG-2026-08-17.md]({archive_path}) — moved, not deleted.\\n'\n\n# Find the archive links section and add the new link\narchive_marker = '> Entries from 2026-08-15 to 2026-08-16 are archived in [docs/archive/CHANGELOG-2026-08-15-to-2026-08-16.md](docs/archive/CHANGELOG-2026-08-15-to-2026-08-16.md) — moved, not deleted.'\ninsert_pos = content.find(archive_marker)\nif insert_pos != -1:\n    end_of_marker = content.find('\\n', insert_pos) + 1\n    content = content[:end_of_marker] + archive_link + content[end_of_marker:]\n\nwith open(filepath, 'w', encoding='utf-8') as f:\n    f.write(content)\n\nprint(f'Archived {len(archived_entries)} entries to {archive_path}')\nprint(f'New size: {len(content)} chars')\n"